"use strict";(self.webpackChunkwhixpdoc=self.webpackChunkwhixpdoc||[]).push([[437],{3592:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Sonrak\u0131","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"Sidebar":[{"type":"category","label":"Giri\u015f","collapsible":false,"items":[{"type":"link","label":"XMPP n\u0259dir?","href":"/az/docs/introduction/what-is-xmpp","docId":"introduction/what-is-xmpp","unlisted":false},{"type":"link","label":"Motivasiya","href":"/az/docs/introduction/motivation","docId":"introduction/motivation","unlisted":false}],"collapsed":false},{"type":"category","label":"Server","collapsible":true,"items":[{"type":"link","label":"D\xfczg\xfcn serveri se\xe7m\u0259k","href":"/az/docs/server/","docId":"server/server","unlisted":false},{"type":"link","label":"Ejabberd IM \xfc\xe7\xfcn \xf6rn\u0259k konfiqurasiya","href":"/az/docs/server/configuration","docId":"server/configuration","unlisted":false},{"type":"link","label":"DirectTLS vs. StartTLS","href":"/az/docs/server/tls","docId":"server/tls","unlisted":false},{"type":"link","label":"Host","href":"/az/docs/server/host","docId":"server/host","unlisted":false}],"collapsed":true},{"type":"category","label":"Anlay\u0131\u015flar","collapsible":false,"items":[{"type":"link","label":"Jabber Identifier","href":"/az/docs/essentials/jid","docId":"essentials/jid","unlisted":false},{"type":"link","label":"Databaza","href":"/az/docs/essentials/database","docId":"essentials/database","unlisted":false},{"type":"link","label":"Autentikasiya","href":"/az/docs/essentials/authentication","docId":"essentials/authentication","unlisted":false},{"type":"link","label":"Loqlama","href":"/az/docs/essentials/log","docId":"essentials/log","unlisted":false},{"type":"link","label":"\u018flaq\u0259 yarad\u0131lmas\u0131","href":"/az/docs/essentials/connection","docId":"essentials/connection","unlisted":false}],"collapsed":false},{"type":"category","label":"\xc7ox v\u0259 daha \xe7ox","collapsible":true,"items":[{"type":"link","label":"Handler\'l\u0259r il\u0259 m\u0259ntiq qurmaq","href":"/az/docs/advanced/handlers","docId":"advanced/handlers","unlisted":false},{"type":"link","label":"\u0130lkin Presence g\xf6nd\u0259rm\u0259k","href":"/az/docs/advanced/presence","docId":"advanced/presence","unlisted":false},{"type":"link","label":"\u0130lkin Message g\xf6nd\u0259rm\u0259k","href":"/az/docs/advanced/message","docId":"advanced/message","unlisted":false},{"type":"link","label":"Stream Management","href":"/az/docs/advanced/sm","docId":"advanced/sm","unlisted":false}],"collapsed":true}]},"docs":{"advanced/handlers":{"id":"advanced/handlers","title":"Handler\'l\u0259r il\u0259 m\u0259ntiq qurmaq","description":"In Whixp, using handlers is essential. Handlers form the backbone of your logic for managing communication messages, stanzas, and errors while interacting with the server. You can explore the source code of this package to gain deeper insights into the use cases for handlers.","sidebar":"Sidebar"},"advanced/message":{"id":"advanced/message","title":"\u0130lkin Message g\xf6nd\u0259rm\u0259k","description":"Messaging is a core functionality of the XMPP protocol, and the Whixp package provides a robust framework for building and sending messages to dedicated recipients.","sidebar":"Sidebar"},"advanced/presence":{"id":"advanced/presence","title":"\u0130lkin Presence g\xf6nd\u0259rm\u0259k","description":"Presence information is a core functionality of the XMPP protocol. It allows users to broadcast their availability status to others on the network. When communicating over XMPP, it is often necessary to send presence notifications to inform others (usually contacts in your roster) about your current status, such as whether you\'re online, offline, away, or busy. These presence updates help users know when they can interact with one another in real-time.","sidebar":"Sidebar"},"advanced/sm":{"id":"advanced/sm","title":"Stream Management","description":"As XMPP operates over persistent TCP connections, stream management provides mechanisms to handle interruptions and maintain session continuity, ensuring that messages and presence updates are delivered even in the face of network instability.","sidebar":"Sidebar"},"essentials/authentication":{"id":"essentials/authentication","title":"Autentikasiya","description":"In XMPP protocol, various mechanisms are employed to authenticate clients, including traditional username/password methods, token-based authentication, and more secure techniques like SASL (Simple Authentication and Security Layer). The choice of authentication mechamism can depend on the specific security requirements and the deployment environment of the XMPP server. This section delives into the authentication methods in XMPP, exploring their functionality, benefits and the usage of several authentication methods in Whixp package.","sidebar":"Sidebar"},"essentials/connection":{"id":"essentials/connection","title":"\u018flaq\u0259 yarad\u0131lmas\u0131","description":"After completing the necessary configuration, it\'s time to establish an initial connection to the XMPP server.","sidebar":"Sidebar"},"essentials/database":{"id":"essentials/database","title":"Databaza","description":"Whixp uses the Hive database as a built-in approach to handle the primitive parats of the package with the local system.","sidebar":"Sidebar"},"essentials/jid":{"id":"essentials/jid","title":"Jabber Identifier","description":"Serves as a unique address for each user. Structurally similar to an email address, a JID comprises a username and a domain, separated by an \\"@\\" symbol\u2014for example, vsevolod@dosy.app. This format ensures that every user on the XMPP network can be uniquely identified and contacted using their JID.","sidebar":"Sidebar"},"essentials/log":{"id":"essentials/log","title":"Loqlama","description":"Logging outputs are essential in applications like Whixp. The library provides an ideal logging system that allows developers to observe the results of each sent stanza and communication message, as well as to be aware of any exceptions that occur while connecting to or communicating with the server. This page explains how to customize the logging system according to your needs.","sidebar":"Sidebar"},"introduction/motivation":{"id":"introduction/motivation","title":"Motivasiya","description":"Whixp leverages XMPP functionalities to provide a robust foundation for Dart and Flutter applications to communicate with XMPP servers. During my search for protocol support in the Flutter environment, I found that while there are officially supported SDKs for protocols like Matrix on pub.dev, XMPP lacked dedicated packages. The available XMPP packages were either discontinued or did not offer the required features for my needs.","sidebar":"Sidebar"},"introduction/what-is-xmpp":{"id":"introduction/what-is-xmpp","title":"XMPP n\u0259dir?","description":"XMPP (Extensible Messaging and Presence Protocol) real vaxtda mesajla\u015fma v\u0259 m\xf6vcudluq m\u0259lumatlar\u0131 \xfc\xe7\xfcn a\xe7\u0131q standart kommunikasiya protokoludur.","sidebar":"Sidebar"},"server/configuration":{"id":"server/configuration","title":"Ejabberd IM \xfc\xe7\xfcn \xf6rn\u0259k konfiqurasiya","description":"This documentation will guide you through configuring your Ejabberd server on a local machine to establish initial connections, and send and receive stanzas.","sidebar":"Sidebar"},"server/host":{"id":"server/host","title":"Host","description":"This section explains how host selection works in Whixp.","sidebar":"Sidebar"},"server/server":{"id":"server/server","title":"D\xfczg\xfcn serveri se\xe7m\u0259k","description":"When selecting a server for your XMPP messaging experience, it\'s crucial to choose the right one to meet your needs. While it\'s possible to develop your own XMPP-compliant server, selecting an existing server that aligns with your requirements can simplify the process. The choice of server is often influenced by the programming language you are familiar with, as XMPP\'s extensibility allows for custom extensions and modifications.","sidebar":"Sidebar"},"server/tls":{"id":"server/tls","title":"DirectTLS vs. StartTLS","description":"DirectTLS and StartTLS are two methods used to secure communications via the Transport Layer Security (TLS) protocol. Although these terms are primarily associated with email communication, they are also applicable to XMPP. Both methods play crucial roles in ensuring secure exchanges of information in various contexts.","sidebar":"Sidebar"}}}}')}}]);